/* src/vs/base/browser/ui/pixelSpinner/pixelSpinner.css */
.monaco-pixel-spinner {
  display: inline-grid;
  grid-template-columns: repeat(2, 2px);
  grid-template-rows: repeat(3, 2px);
  column-gap: 2px;
  row-gap: 2px;
  place-content: center;
  width: 16px;
  height: 16px;
  color: currentColor;
  pointer-events: none;
  contain: layout style size paint;
  isolation: isolate;
  transform: translateZ(0);
}
.monaco-pixel-spinner.monaco-pixel-spinner-paused .monaco-pixel-spinner-dot {
  animation-play-state: paused;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot {
  display: block;
  width: 2px;
  height: 2px;
  border-radius: 50%;
  background-color: currentColor;
  opacity: 0;
  transform: translateY(-4px);
  animation: monaco-pixel-spinner-dot-cycle 1820ms infinite;
  animation-timing-function: steps(6, jump-none);
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(1) {
  animation-delay: 520ms;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(2) {
  animation-delay: 650ms;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(3) {
  animation-delay: 260ms;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(4) {
  animation-delay: 390ms;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(5) {
  animation-name: monaco-pixel-spinner-dot-cycle-long;
}
.monaco-pixel-spinner .monaco-pixel-spinner-dot:nth-child(6) {
  animation-name: monaco-pixel-spinner-dot-cycle-short;
  animation-delay: 130ms;
}
@keyframes monaco-pixel-spinner-dot-cycle {
  0% {
    opacity: 0;
    transform: translateY(-4px);
  }
  9.34%, 57.14% {
    opacity: 1;
    transform: translateY(0);
  }
  66.48%, 100% {
    opacity: 0;
    transform: translateY(7px);
  }
}
@keyframes monaco-pixel-spinner-dot-cycle-long {
  0% {
    opacity: 0;
    transform: translateY(-4px);
  }
  9.34%, 64.29% {
    opacity: 1;
    transform: translateY(0);
  }
  73.63%, 100% {
    opacity: 0;
    transform: translateY(7px);
  }
}
@keyframes monaco-pixel-spinner-dot-cycle-short {
  0% {
    opacity: 0;
    transform: translateY(-4px);
  }
  9.34%, 50% {
    opacity: 1;
    transform: translateY(0);
  }
  59.34%, 100% {
    opacity: 0;
    transform: translateY(7px);
  }
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot {
  animation: monaco-pixel-spinner-ring-pulse 1200ms linear infinite;
  opacity: 0.25;
  transform: none;
  animation-timing-function: steps(4, jump-none);
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(1) {
  animation-delay: 0ms;
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(2) {
  animation-delay: 200ms;
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(3) {
  animation-delay: 1000ms;
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(4) {
  animation-delay: 400ms;
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(5) {
  animation-delay: 800ms;
}
.monaco-pixel-spinner.monaco-pixel-spinner-ring .monaco-pixel-spinner-dot:nth-child(6) {
  animation-delay: 600ms;
}
@keyframes monaco-pixel-spinner-ring-pulse {
  0%, 100% {
    opacity: 0.25;
    transform: none;
  }
  16.67% {
    opacity: 1;
    transform: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  .monaco-pixel-spinner .monaco-pixel-spinner-dot {
    animation: none;
    opacity: 1;
    transform: translateY(0);
  }
}

