  display: none;
}
.prompt-timeline-gutter-rest {
  position: absolute;
  left: var(--prompt-timeline-gutter-handle-left);
  top: 50%;
  transform: translateY(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 4px;
  padding: 8px 6px;
  border: none;
  border-radius: var(--vscode-cornerRadius-small);
  background: transparent;
  color: inherit;
  font: inherit;
  pointer-events: auto;
  cursor: pointer;
  transition: background-color 140ms ease;
