.prompt-timeline-rail-gutter.revealed .prompt-timeline-gutter-rest {
  background-color: var(--vscode-toolbar-hoverBackground);
}
.prompt-timeline-gutter-rest:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: 1px;
}
.prompt-timeline-gutter-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background-color: var(--vscode-descriptionForeground);
  opacity: 0.55;
  transition:
    opacity 140ms ease,
    transform 140ms ease,
    background-color 140ms ease;
}
.prompt-timeline-gutter-rest:hover .prompt-timeline-gutter-dot {
  opacity: 1;
}
.prompt-timeline-gutter-dot.active {
  background-color: var(--vscode-focusBorder);
  opacity: 1;
  transform: scale(1.5);
}
.prompt-timeline-gutter-dot.preview {
  opacity: 1;
  transform: scale(1.5);
}
.prompt-timeline-gutter-dot-more {
  width: 2px;
  height: 8px;
  border-radius: var(--vscode-cornerRadius-circle);
  background-color: var(--vscode-descriptionForeground);
  opacity: 0.4;
  transition: opacity 140ms ease;
}
