.monaco-reduce-motion .prompt-timeline-gutter-dot {
  transition: opacity 140ms ease, background-color 140ms ease;
}
.monaco-reduce-motion .prompt-timeline-gutter-dot.active,
.monaco-reduce-motion .prompt-timeline-gutter-dot.preview {
  transform: none;
}
.prompt-timeline-gutter-panel {
  position: absolute;
  left: calc(var(--prompt-timeline-gutter-handle-left) + var(--prompt-timeline-gutter-handle-width));
  top: 50%;
  transform: translateY(-50%) scale(0.98);
  transform-origin: left center;
  display: flex;
  flex-direction: column;
  width: 260px;
  max-height: calc(100% - 24px);
  padding: 4px;
  box-sizing: border-box;
