  border: 1px solid var(--vscode-editorHoverWidget-border);
  border-radius: var(--vscode-cornerRadius-medium);
  box-shadow: 0 2px 8px var(--vscode-widget-shadow);
  opacity: 0;
  pointer-events: none;
  transition: opacity 140ms ease, transform 140ms ease;
  z-index: 20;
}
.prompt-timeline-rail-gutter.revealed .prompt-timeline-gutter-panel {
  opacity: 1;
  transform: translateY(-50%) scale(1);
  pointer-events: auto;
}
.monaco-reduce-motion .prompt-timeline-gutter-panel {
  transition: opacity 140ms ease;
  transform: translateY(-50%);
}
.monaco-reduce-motion .prompt-timeline-rail-gutter.revealed .prompt-timeline-gutter-panel {
  transform: translateY(-50%);
}
