.chat-debug-message-section-header {
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 4px 8px;
  background: var(--vscode-editorWidget-background);
  border-radius: 3px;
  user-select: none;
  font-weight: 600;
  color: var(--vscode-foreground);
  cursor: pointer;
}
.chat-debug-message-section-header:hover {
  background: var(--vscode-list-hoverBackground);
}
.chat-debug-message-section-chevron {
  flex-shrink: 0;
  width: 16px;
  text-align: center;
}
.chat-debug-message-section-title {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-debug-message-section-content-wrapper {
  border-top: 1px solid var(--vscode-widget-border, transparent);
}
.chat-debug-message-section-content {
  margin: 0;
  padding: 8px 12px;
  white-space: pre-wrap;
  word-break: break-word;
  font-size: 12px;
  font-family: var(--vscode-chat-font-family, monospace);
  background: transparent;
  outline: none;
}
.chat-debug-message-section-content:focus {
  outline: 1px solid var(--vscode-focusBorder);
}
.chat-debug-file-list-row a.chat-inline-anchor-widget {
  cursor: pointer;
}
.chat-debug-settings-gear.monaco-button,
.chat-debug-section-copy-btn.monaco-button {
  flex-shrink: 0;
  opacity: 0.7;
  border-radius: 3px;
  padding: 2px;
  background: none;
  border: none;
  color: inherit;
  min-width: auto;
}
.chat-debug-settings-gear.monaco-button:hover,
.chat-debug-section-copy-btn.monaco-button:hover {
  opacity: 1;
  background: var(--vscode-toolbar-hoverBackground);
}
.chat-debug-settings-gear-header-passthrough,
.chat-debug-section-copy-header-passthrough {
  pointer-events: none;
}
.chat-debug-settings-gear-header-passthrough .chat-debug-settings-gear,
.chat-debug-section-copy-header-passthrough .chat-debug-section-copy-btn {
  pointer-events: auto;
}
.chat-debug-source-folder-content {
  padding: 8px 12px;
  border-top: 1px solid var(--vscode-widget-border, transparent);
}
.chat-debug-source-folder-note {
  margin-bottom: 4px;
}
.chat-debug-source-folder-row {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  padding: 1px 0;
}
.chat-debug-source-folder-index {
  color: var(--vscode-descriptionForeground);
  flex-shrink: 0;
  min-width: 16px;
  text-align: right;
}
.chat-debug-source-folder-label {
  word-break: break-all;
}
.chat-debug-file-list-badge-link {
  cursor: pointer;
}
.chat-debug-flowchart {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  flex: 1;
}
.chat-debug-flowchart-content-wrapper {
  display: flex;
  flex: 1;
  overflow: hidden;
  position: relative;
}
.chat-debug-flowchart-content-wrapper > .chat-debug-detail-panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  z-index: 10;
}
.chat-debug-flowchart-content {
  flex: 1;
  overflow: hidden;
  position: relative;
  cursor: grab;
  background: var(--vscode-editor-background);
}
.chat-debug-flowchart-content:active {
  cursor: grabbing;
}
.chat-debug-flowchart-svg-wrapper {
  transform-origin: 0 0;
  position: absolute;
  top: 0;
  left: 0;
}
.chat-debug-flowchart-svg {
  display: block;
}
.chat-debug-flowchart-node rect {
  transition: opacity 0.15s;
}
.chat-debug-flowchart-node:hover rect:first-child {
  opacity: 0.85;
}
.chat-debug-flowchart-subgraph-header {
  cursor: pointer;
}
.chat-debug-flowchart-subgraph:hover rect.chat-debug-flowchart-subgraph-header {
  opacity: 0.25;
}
.chat-debug-flowchart-focus-ring {
  display: none;
}
.chat-debug-flowchart-node:focus,
.chat-debug-flowchart-node:focus-visible {
  outline: none !important;
}
.chat-debug-flowchart-node:focus .chat-debug-flowchart-focus-ring {
  display: inline;
}
.chat-debug-flowchart-subgraph-header:focus {
  outline: 2px solid var(--vscode-focusBorder);
  outline-offset: 2px;
}
.chat-debug-flowchart-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  font-size: 13px;
  color: var(--vscode-descriptionForeground);
}
.chat-debug-flowchart-show-more {
  display: flex;
  justify-content: center;
  margin: 12px 0 0;
}
.chat-debug-cache {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  flex: 1;
  min-height: 0;
}
.chat-debug-cache-body {
  display: flex;
  flex: 1 1 auto;
  min-height: 0;
  position: relative;
}
.chat-debug-cache-rail {
  border-right: 1px solid var(--vscode-widget-border, transparent);
  background: var(--vscode-sideBar-background);
  display: flex;
  flex-direction: column;
  min-height: 0;
  flex-shrink: 0;
  overflow: hidden;
}
.chat-debug-cache-rail-toolbar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 6px 10px;
  border-bottom: 1px solid var(--vscode-widget-border, transparent);
  flex-shrink: 0;
}
.chat-debug-cache-rail-toolbar:empty {
  display: none;
}
.chat-debug-cache-filter-label {
  font-size: 10.5px;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--vscode-descriptionForeground);
  flex-shrink: 0;
}
.chat-debug-cache-filter-button {
  display: flex;
  align-items: center;
  gap: 4px;
  flex: 1 1 auto;
  min-width: 0;
  padding: 2px 6px;
  font-size: 11.5px;
  color: var(--vscode-foreground);
  background: var(--vscode-button-secondaryBackground, var(--vscode-input-background));
  border: 1px solid var(--vscode-widget-border, transparent);
  border-radius: 4px;
  cursor: pointer;
}
.chat-debug-cache-filter-button:hover {
  background: var(--vscode-button-secondaryHoverBackground, var(--vscode-list-hoverBackground));
}
.chat-debug-cache-filter-button:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: -1px;
}
.chat-debug-cache-filter-button-text {
  flex: 1 1 auto;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-align: left;
}
.chat-debug-cache-filter-chevron {
  font-size: 11px;
  color: var(--vscode-descriptionForeground);
  flex-shrink: 0;
}
.chat-debug-cache-rail-list {
  flex: 1 1 auto;
  overflow-y: auto;
  padding: 4px 0;
}
.chat-debug-cache-group-header {
  padding: 10px 10px 4px 10px;
  border-top: 1px solid var(--vscode-widget-border, transparent);
  display: flex;
  flex-direction: column;
  gap: 2px;
  cursor: pointer;
  user-select: none;
}
.chat-debug-cache-group-header:hover {
  background: var(--vscode-list-hoverBackground);
}
.chat-debug-cache-group-header:focus,
.chat-debug-cache-group-header:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: -1px;
}
.chat-debug-cache-rail-list > .chat-debug-cache-group-header:first-child {
  border-top: none;
}
.chat-debug-cache-group-top {
  display: flex;
  align-items: center;
  gap: 6px;
  min-width: 0;
}
.chat-debug-cache-group-chev::before {
  content: "\25be";
  display: inline-block;
  width: 10px;
  color: var(--vscode-descriptionForeground);
  font-size: 10px;
  transition: transform 0.15s;
}
.chat-debug-cache-group-header.is-collapsed .chat-debug-cache-group-chev::before {
  transform: rotate(-90deg);
}
.chat-debug-cache-group-prompt {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--vscode-foreground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  flex: 1 1 auto;
  min-width: 0;
}
.chat-debug-cache-group-count {
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-badge-foreground);
  background: var(--vscode-badge-background);
  padding: 1px 7px;
  border-radius: 10px;
  flex-shrink: 0;
}
.chat-debug-cache-group-meta {
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  margin-left: 16px;
}
.chat-debug-cache-request-id {
  font-family: var(--monaco-monospace-font);
  user-select: text;
  cursor: text;
  overflow-wrap: anywhere;
  text-align: right;
}
.chat-debug-cache-turn {
  padding: 6px 10px;
  display: grid;
  grid-template-columns: 24px 1fr;
  gap: 2px 8px;
  align-items: start;
  cursor: pointer;
  border-left: 3px solid transparent;
}
.chat-debug-cache-turn:hover {
  background: var(--vscode-list-hoverBackground);
}
.chat-debug-cache-turn:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: -1px;
}
.chat-debug-cache-turn.is-selected {
  border-left-color: var(--vscode-focusBorder);
  background: var(--vscode-list-activeSelectionBackground);
  color: var(--vscode-list-activeSelectionForeground);
}
.chat-debug-cache-turn-idx {
  font-family: var(--monaco-monospace-font);
  color: var(--vscode-descriptionForeground);
  font-size: 11px;
  text-align: right;
  padding-top: 1px;
}
.chat-debug-cache-turn-main {
  overflow: hidden;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.chat-debug-cache-turn-top {
  font-size: 11.5px;
  color: var(--vscode-foreground);
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 4px;
  min-width: 0;
}
.chat-debug-cache-turn-source {
  font-weight: 600;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  max-width: 100%;
}
.chat-debug-cache-turn-chip {
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-turn-hit.is-bad {
  color: var(--vscode-charts-red);
  font-weight: 600;
}
.chat-debug-cache-turn-sub {
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-debug-cache-content {
  overflow-y: auto;
  padding: 16px 24px;
  display: flex;
  flex-direction: column;
  gap: 16px;
  min-width: 0;
  flex: 1 1 auto;
}
.chat-debug-cache-empty {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-title-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.chat-debug-cache-title {
  margin: 0;
  font-size: 14px;
  color: var(--vscode-foreground);
}
.chat-debug-cache-title-actions {
  display: flex;
  gap: 6px;
}
.chat-debug-cache-summary {
  display: grid;
  grid-template-columns: 1fr 1fr 1.5fr;
  gap: 12px;
}
.chat-debug-cache-card {
  background: var(--vscode-editorWidget-background);
  border: 1px solid var(--vscode-widget-border, var(--vscode-editorWidget-border));
  border-radius: 6px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.chat-debug-cache-card.break.is-critical {
  border-color: var(--vscode-charts-red);
}
.chat-debug-cache-card.break.is-warning {
  border-color: var(--vscode-charts-yellow);
}
.chat-debug-cache-card.break.is-ok,
.chat-debug-cache-card.break.is-info {
  border-color: var(--vscode-charts-green);
}
.chat-debug-cache-findings {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.chat-debug-cache-finding {
  display: grid;
  grid-template-columns: 16px 1fr;
  gap: 8px;
  align-items: start;
  margin: 0;
  padding: 0;
  background: transparent;
  border: none;
  text-align: left;
  color: inherit;
  font-family: inherit;
  font-size: inherit;
}
button.chat-debug-cache-finding.is-clickable {
  cursor: pointer;
  border-radius: 4px;
}
button.chat-debug-cache-finding.is-clickable:hover .chat-debug-cache-finding-title {
  text-decoration: underline;
}
button.chat-debug-cache-finding.is-clickable:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: 2px;
}
.chat-debug-cache-finding-icon {
  font-size: 14px;
  padding-top: 1px;
}
.chat-debug-cache-finding-icon.is-ok {
  color: var(--vscode-charts-green);
}
.chat-debug-cache-finding-icon.is-info {
  color: var(--vscode-charts-blue);
}
.chat-debug-cache-finding-icon.is-warning {
  color: var(--vscode-charts-yellow);
}
.chat-debug-cache-finding-icon.is-critical {
  color: var(--vscode-charts-red);
}
.chat-debug-cache-finding-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
}
.chat-debug-cache-finding-title {
  font-size: 11.5px;
  font-weight: 600;
  color: var(--vscode-foreground);
}
.chat-debug-cache-finding-detail {
  font-family: var(--monaco-monospace-font);
  font-size: 11px;
  line-height: 1.5;
  color: var(--vscode-foreground);
}
.chat-debug-cache-finding-hint {
  font-size: 11px;
  line-height: 1.5;
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-session-health {
  background: var(--vscode-editorWidget-background);
  border: 1px solid var(--vscode-widget-border, var(--vscode-editorWidget-border));
  border-radius: 6px;
  padding: 10px 12px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.chat-debug-cache-session-health-stats {
  font-family: var(--monaco-monospace-font);
  font-size: 11.5px;
  color: var(--vscode-foreground);
}
.chat-debug-cache-session-health-chips {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.chat-debug-cache-session-health-chip {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  padding: 2px 8px;
  border-radius: 10px;
  border: 1px solid var(--vscode-widget-border, transparent);
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-session-health-chip .codicon {
  font-size: 12px;
}
.chat-debug-cache-session-health-chip.cause-tools,
.chat-debug-cache-session-health-chip.cause-system,
.chat-debug-cache-session-health-chip.cause-model,
.chat-debug-cache-session-health-chip.cause-options,
.chat-debug-cache-session-health-chip.cause-history {
  color: var(--vscode-charts-red);
  border-color: var(--vscode-charts-red);
}
.chat-debug-cache-session-health-chip.cause-expiration {
  color: var(--vscode-charts-yellow);
  border-color: var(--vscode-charts-yellow);
}
.chat-debug-cache-rail-gap {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 3px 10px;
  font-family: var(--monaco-monospace-font);
  font-size: 10px;
  color: var(--vscode-charts-yellow);
  opacity: 0.9;
}
.chat-debug-cache-rail-gap .codicon {
  font-size: 11px;
}
.chat-debug-cache-rail-gap::before,
.chat-debug-cache-rail-gap::after {
  content: "";
  flex: 1 1 auto;
  border-top: 1px dashed color-mix(in srgb, var(--vscode-charts-yellow) 50%, transparent);
}
.chat-debug-cache-card-h {
  display: flex;
  align-items: center;
  gap: 6px;
  font-size: 11px;
  color: var(--vscode-descriptionForeground);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.chat-debug-cache-card-headline {
  font-size: 14px;
  font-weight: 600;
  color: var(--vscode-foreground);
}
.chat-debug-cache-card-sub {
  font-size: 11.5px;
  color: var(--vscode-foreground);
}
.chat-debug-cache-perf-rule {
  height: 1px;
  background: var(--vscode-widget-border, var(--vscode-editorWidget-border));
  margin: 12px 0 4px;
}
.chat-debug-cache-perf-section-h {
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  text-transform: uppercase;
  letter-spacing: 0.05em;
  margin-bottom: 4px;
}
.chat-debug-cache-perf-line {
  font-family: var(--monaco-monospace-font);
  font-size: 11.5px;
  color: var(--vscode-foreground);
  line-height: 1.5;
}
.chat-debug-cache-request-shape-note {
  margin-top: 6px;
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-options-banner {
  font-family: var(--monaco-monospace-font);
  font-size: 11.5px;
  color: var(--vscode-charts-yellow);
  background: var(--vscode-editorWidget-background);
  border: 1px solid var(--vscode-charts-yellow);
  border-radius: 4px;
  padding: 6px 10px;
}
.chat-debug-cache-options-table {
  display: flex;
  flex-direction: column;
  border: 1px solid var(--vscode-widget-border, var(--vscode-editorWidget-border));
  border-radius: 6px;
  overflow: hidden;
}
.chat-debug-cache-options-row {
  display: grid;
  grid-template-columns: 200px 1fr 1fr;
  gap: 12px;
  padding: 6px 12px;
  font-family: var(--monaco-monospace-font);
  font-size: 11.5px;
  border-top: 1px solid var(--vscode-widget-border, var(--vscode-editorWidget-border));
}
.chat-debug-cache-options-row:first-child {
  border-top: none;
}
.chat-debug-cache-options-row.head {
  background: var(--vscode-editorWidget-background);
  color: var(--vscode-descriptionForeground);
  text-transform: uppercase;
  font-size: 10.5px;
  letter-spacing: 0.05em;
}
.chat-debug-cache-options-row.changed {
  background: var(--vscode-diffEditor-removedLineBackground, rgba(244, 135, 113, 0.08));
}
.chat-debug-cache-options-cell {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.chat-debug-cache-options-cell.key {
  color: var(--vscode-descriptionForeground);
}
.chat-debug-cache-kv {
  display: flex;
  justify-content: space-between;
  gap: 12px;
  font-family: var(--monaco-monospace-font);
  font-size: 11.5px;
  flex-wrap: wrap;
}
.chat-debug-cache-kv .k {
  color: var(--vscode-descriptionForeground);
  flex-shrink: 0;
}
.chat-debug-cache-kv .v {
  color: var(--vscode-foreground);
  min-width: 0;
}
.chat-debug-cache-section-h {
  margin: 0 0 8px;
  font-size: 12px;
  color: var(--vscode-foreground);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.chat-debug-cache-sig-legend {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  margin-bottom: 8px;
}
.chat-debug-cache-sig-legend-entry {
  display: inline-flex;
  align-items: center;
  gap: 6px;
}
.chat-debug-cache-sig-swatch {
  display: inline-block;
  width: 12px;
  height: 12px;
  border-radius: 2px;
}
.chat-debug-cache-sig-swatch.role-system {
  background: var(--vscode-charts-purple, #b292ff);
}
.chat-debug-cache-sig-swatch.role-tools {
  background: var(--vscode-charts-orange, #d9822b);
}
.chat-debug-cache-sig-swatch.role-user {
  background: var(--vscode-charts-blue);
}
.chat-debug-cache-sig-swatch.role-assistant {
  background: var(--vscode-charts-green);
}
.chat-debug-cache-sig-swatch.role-tool {
  background: var(--vscode-charts-yellow);
}
.chat-debug-cache-sig-swatch.role-tool-search {
  background: var(--vscode-charts-foreground, #56b6c2);
}
.chat-debug-cache-sig-swatch.role-drift {
  background: transparent;
  outline: 2px solid var(--vscode-charts-red);
  outline-offset: -2px;
}
.chat-debug-cache-sig-lanes {
  display: flex;
  flex-direction: column;
  gap: 6px;
  background: var(--vscode-editorWidget-background);
  border: 1px solid var(--vscode-widget-border, var(--vscode-editorWidget-border));
  border-radius: 6px;
  padding: 12px 14px;
}
.chat-debug-cache-sig-lane-row {
  display: grid;
  grid-template-columns: 70px 1fr 110px;
  gap: 10px;
  align-items: center;
}
.chat-debug-cache-sig-lane-label {
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
.chat-debug-cache-sig-lane-total {
  font-family: var(--monaco-monospace-font);
  font-size: 10.5px;
  color: var(--vscode-descriptionForeground);
  text-align: right;
}
.chat-debug-cache-sig-bar {
  height: 22px;
  background: var(--vscode-input-background, #2a2a2a);
  border-radius: 4px;
  overflow: hidden;
  display: flex;
  position: relative;
}
.chat-debug-cache-sig-seg {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
