  .monaco-list:focus .monaco-list-row.selected .agent-session-icon > .codicon,
  .monaco-list:focus .monaco-list-row.selected .agent-session-icon > .monaco-pixel-spinner {
    color: var(--vscode-list-activeSelectionForeground) !important;
  }
  .monaco-list-row.selected .agent-session-item,
  .monaco-list-row.selected .agent-session-title {
    color: unset;
  }
  .monaco-list:not(:focus) .monaco-list-row.selected .agent-session-details-row {
    color: var(--vscode-descriptionForeground);
  }
  .monaco-list-row .agent-session-pinned-indicator {
    display: none;
    height: 16px;
    align-items: center;
    color: var(--vscode-descriptionForeground);
    font-size: 12px;
    pointer-events: none;
    &.visible {
      display: flex;
    }
  }
  .monaco-list-row .agent-session-pending-voice-indicator {
    display: none;
    height: 16px;
    align-items: center;
    margin-left: 4px;
    color: var(--vscode-charts-blue);
    font-size: 12px;
    pointer-events: none;
    &.visible {
      display: flex;
    }
  }
  .monaco-list-row .agent-session-title-toolbar {
    position: relative;
    height: 16px;
    display: none;
    .monaco-toolbar {
      position: relative;
      right: 0;
      top: 0;
    }
  }
  .monaco-list-row:hover,
  .monaco-list-row.focused:not(.selected) {
    .agent-session-pinned-indicator {
      display: none;
    }
    .agent-session-title-toolbar {
      display: block;
    }
    .agent-session-title {
      margin-right: 8px;
    }
  }
  .agent-session-item {
    display: flex;
    flex-direction: row;
    padding: 8px 6px;
    &.archived {
      color: var(--vscode-descriptionForeground);
    }
    .agent-session-main-col,
    .agent-session-title-row,
    .agent-session-details-row {
      flex: 1;
      min-width: 0;
    }
    .agent-session-icon-col {
      display: flex;
      align-items: flex-start;
      line-height: 17px;
      .agent-session-icon {
        flex-shrink: 0;
        font-size: var(--vscode-codiconFontSize, 16px);
        height: 16px;
        display: flex;
        align-items: center;
        justify-content: center;
        &.needs-input {
          animation: agent-session-needs-input-pulse 2s ease-in-out infinite;
        }
        @media (prefers-reduced-motion: reduce) {
          &.needs-input {
            animation: none;
          }
        }
      }
    }
    .agent-session-main-col {
      padding-left: 6px;
    }
    .agent-session-title-row,
    .agent-session-details-row {
      display: flex;
      align-items: center;
    }
    .agent-session-title-row {
      line-height: 17px;
      padding-bottom: 4px;
    }
    .agent-session-details-row {
      gap: 4px;
      font-size: 12px;
      line-height: 15px;
      max-height: 15px;
      color: var(--vscode-descriptionForeground);
      .agent-session-details-icon {
        display: none;
        font-size: 11px;
        line-height: 1;
        flex-shrink: 0;
        &.visible {
          display: flex;
          align-items: center;
        }
      }
      .rendered-markdown {
        p {
          display: flex;
          align-items: center;
          margin: 0;
          > span.codicon {
            margin-right: 2px;
          }
        }
        a {
          color: var(--vscode-descriptionForeground);
        }
      }
      .agent-session-diff-container {
        font-variant-numeric: tabular-nums;
        overflow: hidden;
      }
      .agent-session-diff-container {
        display: flex;
        gap: 4px;
        &:not(.has-diff) {
          display: none;
        }
        .agent-session-diff-added {
          color: var(--vscode-chat-linesAddedForeground);
        }
        .agent-session-diff-removed {
          color: var(--vscode-chat-linesRemovedForeground);
        }
      }
      .agent-session-separator {
        display: none;
        &.has-separator {
          display: inline;
          &::before {
            content: "\b7";
          }
        }
      }
      .agent-session-badge {
        p {
          overflow: hidden;
        }
        &:not(.has-badge) {
          display: none;
        }
      }
    }
    .agent-session-title,
    .agent-session-description {
      flex: 1;
      overflow: hidden;
      white-space: nowrap;
      text-overflow: ellipsis;
    }
    .agent-session-description:empty {
      display: none;
    }
    .agent-session-description.has-separator::before {
      content: "\b7";
      margin-right: 4px;
    }
    .agent-session-title {
      font-size: 13px;
    }
    .agent-session-status {
      display: flex;
      align-items: center;
      font-variant-numeric: tabular-nums;
      white-space: nowrap;
      &.has-separator::before {
        content: "\b7";
        margin-right: 4px;
      }
      &.hidden {
        display: none;
      }
    }
    .agent-session-approval-row {
      display: none;
      align-items: flex-end;
      gap: 8px;
      margin-top: 4px;
      padding: 4px 8px;
      box-sizing: border-box;
      border: 1px solid var(--vscode-contrastBorder, var(--vscode-widget-border, transparent));
      border-radius: 4px;
      background-color: var(--vscode-editor-background);
      color: var(--vscode-editor-foreground);
      &.visible {
        display: flex;
      }
      .agent-session-approval-label {
        flex: 1;
        overflow: hidden;
        min-width: 0;
        & > .rendered-markdown,
        & > .rendered-markdown > .code,
        & > .rendered-markdown > .code > span {
          display: block;
          overflow: hidden;
        }
        .monaco-tokenized-source {
          display: block;
          overflow: hidden;
          white-space: nowrap;
          text-overflow: ellipsis;
          font-size: 12px;
        }
      }
      .agent-session-approval-button {
        flex-shrink: 0;
        .monaco-button {
          padding: 2px 10px;
          font-size: 12px;
          white-space: nowrap;
        }
      }
    }
  }
  .agent-session-show-more {
    display: flex;
    align-items: center;
    font-size: 12px;
    color: var(--vscode-foreground);
    padding: 0 6px 0 24px;
    cursor: pointer;
    text-decoration: none !important;
  }
  .agent-session-section {
    display: flex;
    align-items: center;
    font-size: 11px;
    font-weight: 500;
    color: var(--vscode-descriptionForeground);
    text-transform: uppercase;
    padding: 0 6px;
    .agent-session-section-label {
      flex: 1;
      min-width: 0;
      overflow: hidden;
      text-overflow: ellipsis;
      white-space: nowrap;
    }
    .agent-session-section-count {
      opacity: 0.7;
      margin-right: 4px;
    }
    .agent-session-section-toolbar {
      position: relative;
      .monaco-toolbar {
        position: absolute;
        right: 0;
        top: 0;
        display: none;
      }
    }
  }
  .monaco-list-row:hover .agent-session-section .agent-session-section-count {
    display: none;
  }
  .monaco-list-row:hover .agent-session-section .agent-session-section-toolbar,
  .monaco-list-row.focused:not(.selected) .agent-session-section .agent-session-section-toolbar {
    width: 22px;
    .monaco-toolbar {
      display: block;
    }
  }
  .monaco-list:focus .monaco-list-row.focused.selected .agent-session-section-label,
  .monaco-list:focus .monaco-list-row.selected .agent-session-section-label {
    color: var(--vscode-list-activeSelectionForeground);
  }
  .monaco-list:not(:focus) .monaco-list-row.selected .agent-session-section-label {
    color: var(--vscode-list-inactiveSelectionForeground);
  }
  .agent-sessions-empty-filter-message {
    padding: 8px 12px;
    font-size: 12px;
    color: var(--vscode-descriptionForeground);
    .reset-filter-link {
      color: var(--vscode-textLink-foreground);
      cursor: pointer;
      text-decoration: none;
      &:hover {
        text-decoration: underline;
      }
      &:focus-visible {
        text-decoration: underline;
        outline: 1px solid var(--vscode-focusBorder);
        outline-offset: 1px;
      }
    }
  }
}
@keyframes agent-session-needs-input-pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.4;
  }
}
@keyframes agent-session-needs-input-accent-pulse {
  0%, 100% {
    background-color: transparent;
  }
  50% {
    background-color: color-mix(in srgb, var(--vscode-list-warningForeground) 12%, transparent);
  }
}

/* src/vs/workbench/contrib/chat/browser/agentSessions/media/agentSessionHoverWidget.css */
.agent-session-hover {
  display: flex;
  flex-direction: column;
  .agent-session-hover-loading {
    display: flex;
    align-items: center;
    justify-content: center;
    height: 100%;
    color: var(--vscode-descriptionForeground);
  }
  .agent-session-hover-header {
    height: 60px;
    padding: 0 12px;
    border-bottom: 1px solid var(--vscode-widget-border);
    flex-shrink: 0;
    display: flex;
    flex-direction: column;
    justify-content: center;
  }
  .agent-session-hover-title {
    font-weight: 600;
    font-size: 13px;
    margin-bottom: 4px;
    color: var(--vscode-foreground);
    display: flex;
    align-items: center;
    gap: 6px;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .agent-session-hover-details {
    font-size: 11px;
    color: var(--vscode-descriptionForeground);
    display: flex;
    align-items: center;
    gap: 4px;
    flex-wrap: wrap;
    .codicon {
      display: flex;
      align-items: center;
    }
  }
  .agent-session-hover-details .separator {
    opacity: 0.5;
  }
  .agent-session-hover-diff {
    display: flex;
    align-items: center;
    gap: 4px;
  }
  .agent-session-hover-diff .insertions {
    color: var(--vscode-chat-linesAddedForeground);
  }
  .agent-session-hover-diff .deletions {
    color: var(--vscode-chat-linesRemovedForeground);
  }
  .agent-session-hover-content {
    flex: 1;
    min-height: 0;
    opacity: 0;
    animation: agentSessionHoverFadeIn 0.2s ease-out forwards;
    margin: 0 -8px;
    .interactive-session .interactive-item-container {
      padding: 0;
    }
  }
}
@keyframes agentSessionHoverFadeIn {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

