/* src/vs/workbench/contrib/chat/browser/chatStatus/media/chatStatus.css */
.chat-status-bar-entry-tooltip {
  padding: 8px;
  min-width: 320px;
  max-width: 360px;
}
.chat-status-bar-entry-tooltip hr {
  margin-top: 14px;
  margin-bottom: 14px;
}
.chat-status-bar-entry-tooltip .collapsible-header {
  display: flex;
  align-items: center;
  gap: 6px;
  width: 100%;
  padding: 6px 0 6px 0;
  border: none;
  border-top: 1px solid var(--vscode-editorWidget-border);
  background: none;
  cursor: pointer;
  font-size: 13px;
  font-family: inherit;
  font-weight: 400;
  color: var(--vscode-foreground);
}
.chat-status-bar-entry-tooltip .collapsible-header.no-border {
  border-top: none;
  margin-top: 0;
}
.chat-status-bar-entry-tooltip .collapsible-header.non-collapsible {
  cursor: default;
}
.chat-status-bar-entry-tooltip .contributed-section {
  display: flex;
  flex-direction: column;
}
.chat-status-bar-entry-tooltip .collapsible-header:focus {
  outline: none;
}
.chat-status-bar-entry-tooltip .collapsible-header:focus-visible {
  outline: 1px solid var(--vscode-focusBorder);
  outline-offset: -1px;
}
.chat-status-bar-entry-tooltip .collapsible-chevron {
  font-size: 12px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  opacity: 0.7;
  margin-top: 2px;
}
.chat-status-bar-entry-tooltip .contributed-info-icon {
  font-size: 12px;
  display: flex;
  align-items: center;
  flex-shrink: 0;
  opacity: 0.7;
  color: var(--vscode-descriptionForeground);
}
.chat-status-bar-entry-tooltip .collapsible-label {
  white-space: nowrap;
  flex-shrink: 0;
}
.chat-status-bar-entry-tooltip .collapsible-status {
  margin-left: auto;
  font-size: 12px;
  font-weight: 400;
  color: var(--vscode-descriptionForeground);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
}
.chat-status-bar-entry-tooltip .section-description {
  font-size: 12px;
  line-height: 16px;
  color: var(--vscode-descriptionForeground);
}
.chat-status-bar-entry-tooltip .section-description .monaco-link {
  white-space: nowrap;
}
.chat-status-bar-entry-tooltip .section-detail {
  font-size: 12px;
  line-height: 16px;
  color: var(--vscode-descriptionForeground);
}
.chat-status-bar-entry-tooltip .contributed-detail {
  font-size: 12px;
  line-height: 16px;
  font-weight: 400;
  color: var(--vscode-descriptionForeground);
  min-width: 0;
  padding-bottom: 6px;
  white-space: normal;
}
.chat-status-bar-entry-tooltip .collapsible-content {
  display: grid;
  grid-template-rows: 1fr;
  transition: grid-template-rows 200ms ease;
}
.chat-status-bar-entry-tooltip .collapsible-content.collapsed {
  grid-template-rows: 0fr;
}
.chat-status-bar-entry-tooltip .collapsible-content > .collapsible-inner {
  overflow-y: clip;
  overflow-x: visible;
  min-height: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 10px;
  margin-bottom: 4px;
}
.chat-status-bar-entry-tooltip .collapsible-content.collapsed > .collapsible-inner {
  margin-top: 0;
  margin-bottom: 0;
}
.chat-status-bar-entry-tooltip .collapsible-content > .collapsible-inner > hr {
  margin: 0;
}
@media (prefers-reduced-motion: reduce) {
  .chat-status-bar-entry-tooltip .collapsible-content {
    transition: none;
  }
}
.chat-status-bar-entry-tooltip div.header {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--vscode-foreground);
  font-size: 13px;
  line-height: 18px;
  padding-bottom: 10px;
  margin-bottom: 6px;
  border-bottom: 1px solid var(--vscode-editorWidget-border);
  font-weight: 400;
}
.chat-status-bar-entry-tooltip div.header .header-label {
  flex-grow: 1;
  font-weight: 400;
