.onboarding-a-personalize {
  display: flex;
  flex-direction: column;
  gap: 0;
  flex: 1;
  width: 100%;
  min-height: 0;
  margin: 0 auto;
  padding: 0;
}
.onboarding-a-personalize > .onboarding-a-sessions-tip {
