  }
}

/* src/vs/workbench/contrib/onboarding/browser/media/onboardingTarget.css */
.onboarding-target-pulse {
  animation: onboarding-target-pulse 1.4s ease-out infinite;
  outline: var(--vscode-strokeThickness) solid var(--vscode-focusBorder);
  outline-offset: 2px;
}
@media (prefers-reduced-motion: reduce) {
  .onboarding-target-pulse {
    animation: none;
  }
}
@keyframes onboarding-target-pulse {
  0% {
    box-shadow: 0 0 0 0 var(--vscode-focusBorder);
  }
  70% {
    box-shadow: 0 0 0 6px transparent;
  }
  100% {
    box-shadow: 0 0 0 0 transparent;
  }
}

/* src/vs/workbench/contrib/onboarding/browser/media/spotlight.css */
.spotlight-overlay {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 2600;
}
.spotlight-overlay.target-overlay-visible {
  z-index: 1999;
}
.spotlight-blocker {
  position: fixed;
  inset: 0;
  pointer-events: auto;
}
.spotlight-hole {
  position: fixed;
  border-radius: var(--vscode-cornerRadius-medium);
  pointer-events: none;
  box-shadow: 0 0 0 9999px rgba(0, 0, 0, 0.5), 0 0 0 2px var(--vscode-focusBorder) inset;
  transition:
    top 0.2s ease,
    left 0.2s ease,
    width 0.2s ease,
    height 0.2s ease;
}
.spotlight-callout-pointer {
  position: fixed;
  box-sizing: border-box;
  width: var(--vscode-spacing-size100);
  height: var(--vscode-spacing-size100);
  z-index: 1;
  pointer-events: none;
}
.spotlight-callout-pointer::after {
  content: "";
  position: absolute;
  inset: 0;
  background: var(--vscode-editorWidget-background);
  border-right: var(--vscode-strokeThickness) solid var(--vscode-widget-border, transparent);
  border-bottom: var(--vscode-strokeThickness) solid var(--vscode-widget-border, transparent);
}
.spotlight-callout-pointer.top::after {
  transform: rotate(225deg);
}
.spotlight-callout-pointer.right::after {
  transform: rotate(315deg);
}
.spotlight-callout-pointer.bottom::after {
  transform: rotate(45deg);
}
.spotlight-callout-pointer.left::after {
  transform: rotate(135deg);
}
.spotlight-callout {
  position: fixed;
  box-sizing: border-box;
  z-index: 0;
  width: 320px;
  max-width: calc(100vw - var(--vscode-spacing-size320));
  padding: var(--vscode-spacing-size160);
  background: var(--vscode-editorWidget-background);
  color: var(--vscode-editorWidget-foreground);
  border: var(--vscode-strokeThickness) solid var(--vscode-widget-border, transparent);
  border-radius: var(--vscode-cornerRadius-large);
  box-shadow: 0 2px 8px var(--vscode-widget-shadow, rgba(0, 0, 0, 0.36));
  pointer-events: auto;
